void transfer(Account* from, Account* to, int amt) {
    lock(&from->m);
    lock(&to->m);
    from->balance -= amt;
    to->balance += amt;
    unlock(&to->m);
    unlock(&from->m);
}
// thread 1: transfer(A, B, 100)   thread 2: transfer(B, A, 50)
